// Package migrate is generated by ent for schema creation and, in this
// file only, hand written to provide the versioned-migration runtime this
// project actually uses instead of ent's automatic Schema.Create
// diff-and-apply. Code generation only ever (re)writes migrate.go and
// schema.go into this directory by fixed name; it never scans the
// directory and deletes anything, so this file coexists safely with the
// generated ones, the same way internal/ent/embedded.go already coexists
// with generated files directly in internal/ent.
//
// Coverage note: this package's own hand-written logic (apply.go) is
// 90%+ covered per function; apply_test.go and apply_internal_test.go
// force every realistically reachable failure for real (a closed
// connection, a malformed schema_migrations table, a conflicting
// CREATE TABLE, an unrecognized or gapped applied-migrations history),
// per this project's RULE 0. What remains uncovered are mid-transaction
// driver failures (BeginTx, the schema_migrations INSERT, and Commit
// inside applyOne) that need real fault injection to trigger without
// mocking the behavior under test, the same accepted, documented
// limitation internal/storage/ent_unitofwork.go carries for its own
// Commit failure branch. migrate.go's generated Create/WriteTo show 0%
// because production code now deliberately bypasses them (WriteTo is
// used only by the offline, //go:build ignore internal/ent/migrate/gen
// tool, excluded from normal coverage instrumentation); they are not
// hand-written logic this phase owns.
package migrate

import (
	"context"
	"database/sql"
	"embed"
	"fmt"
	"io/fs"
	"sort"
	"time"
)

// sqliteMigrations embeds every committed SQLite migration file so the
// built binary carries them, needing no external file at runtime.
//
//go:embed migrations/sqlite/*.sql
var sqliteMigrations embed.FS

// postgresMigrations embeds every committed Postgres migration file, for
// the same reason.
//
// This set starts at one squashed 0001_initial.sql rather than mirroring
// SQLite's four-file history, and that is correct rather than a lost
// history: a migration ledger is per database, ent can only ever diff
// against the schema it desires today, and no Postgres database has ever
// been migrated by this project. The two dialects diverge in file count
// here and stay in lockstep from here on, since every later schema change
// is generated for both.
//
//go:embed migrations/postgres/*.sql
var postgresMigrations embed.FS

// migrationSource pairs an embedded filesystem with the directory inside
// it holding one dialect's migration files, plus the one statement whose
// text genuinely differs between dialects.
type migrationSource struct {
	fsys embed.FS
	dir  string

	// insertVersion is the parameterized statement recording one
	// migration as applied. It lives here, beside the dialect it belongs
	// to, because placeholder syntax is dialect-specific and
	// database/sql does not normalize it: lib/pq rejects "?" outright
	// ("pq: syntax error at or near ,"), and it rejects it inside the
	// same transaction as the migration's own DDL, so the DDL rolls back
	// too and the failure reads as broken DDL rather than as a wrong
	// placeholder. Every dialect's statement stays parameterized; only
	// the placeholder spelling changes.
	insertVersion string
}

// migrationSources maps a driver dialect name (entgo.io/ent/dialect's
// SQLite/Postgres/MySQL constants) to its embedded migration files.
//
// Both dialects' files are produced by internal/ent/migrate/gen, never
// hand written, and parity_test.go asserts the two sets stay in step, so
// regenerating one dialect and forgetting the other fails the build
// instead of drifting silently.
var migrationSources = map[string]migrationSource{
	"sqlite3": {
		fsys:          sqliteMigrations,
		dir:           "migrations/sqlite",
		insertVersion: `INSERT INTO schema_migrations (version, applied_at) VALUES (?, ?)`,
	},
	"postgres": {
		fsys:          postgresMigrations,
		dir:           "migrations/postgres",
		insertVersion: `INSERT INTO schema_migrations (version, applied_at) VALUES ($1, $2)`,
	},
}

// Apply brings db up to the latest schema version for dialectName by
// executing every embedded migration file for that dialect not already
// recorded as applied, in filename order, each inside its own
// transaction. It is the versioned-migration replacement for ent's
// automatic Schema.Create.
//
// Apply is also the startup schema-version gate: it fails closed, rather
// than silently continuing, if db already has a migration recorded that
// this binary's embedded set does not recognize (an older binary running
// against a database a newer binary already migrated further), or if the
// recorded history has a gap before its highest applied version (a
// partially migrated or tampered database).
func Apply(ctx context.Context, dialectName string, db *sql.DB) error {
	src, ok := migrationSources[dialectName]
	if !ok {
		return fmt.Errorf("migrate: no embedded migrations for dialect %q", dialectName)
	}

	names, err := migrationNames(src)
	if err != nil {
		return err
	}
	if err := ensureVersionTable(ctx, db); err != nil {
		return err
	}
	applied, err := appliedVersions(ctx, db)
	if err != nil {
		return err
	}
	if err := checkGate(names, applied); err != nil {
		return err
	}

	for _, name := range names {
		if applied[name] {
			continue
		}
		script, err := fs.ReadFile(src.fsys, src.dir+"/"+name)
		if err != nil {
			return fmt.Errorf("migrate: reading %s: %w", name, err)
		}
		if err := applyOne(ctx, db, src.insertVersion, name, string(script)); err != nil {
			return err
		}
	}
	return nil
}

// migrationNames lists a dialect's embedded migration filenames in
// ascending (application) order. Filenames are numbered
// (0001_initial.sql, 0002_..., ...), so a plain lexicographic sort is the
// correct application order.
func migrationNames(src migrationSource) ([]string, error) {
	entries, err := fs.ReadDir(src.fsys, src.dir)
	if err != nil {
		return nil, fmt.Errorf("migrate: reading embedded migration directory %q: %w", src.dir, err)
	}
	names := make([]string, 0, len(entries))
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		names = append(names, e.Name())
	}
	sort.Strings(names)
	return names, nil
}

// ensureVersionTable creates the migration-tracking table if this is the
// first time Apply has run against db. It is intentionally a separate
// table from anything ent generates, so it can never collide with a
// domain schema change.
func ensureVersionTable(ctx context.Context, db *sql.DB) error {
	if _, err := db.ExecContext(ctx, `CREATE TABLE IF NOT EXISTS schema_migrations (
		version TEXT PRIMARY KEY,
		applied_at TIMESTAMP NOT NULL
	)`); err != nil {
		return fmt.Errorf("migrate: creating schema_migrations table: %w", err)
	}
	return nil
}

// appliedVersions returns the set of migration filenames db already has
// recorded as applied.
func appliedVersions(ctx context.Context, db *sql.DB) (map[string]bool, error) {
	rows, err := db.QueryContext(ctx, `SELECT version FROM schema_migrations`)
	if err != nil {
		return nil, fmt.Errorf("migrate: reading schema_migrations: %w", err)
	}
	defer rows.Close()

	applied := make(map[string]bool)
	for rows.Next() {
		var version string
		if err := rows.Scan(&version); err != nil {
			return nil, fmt.Errorf("migrate: scanning schema_migrations row: %w", err)
		}
		applied[version] = true
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("migrate: iterating schema_migrations: %w", err)
	}
	return applied, nil
}

// checkGate is the startup schema-version gate described on Apply. It
// fails closed rather than silently proceeding when db's recorded
// history disagrees with what this binary's embedded migration set can
// explain.
func checkGate(known []string, applied map[string]bool) error {
	knownSet := make(map[string]bool, len(known))
	for _, name := range known {
		knownSet[name] = true
	}

	// Every applied version must be one this binary recognizes. An
	// unrecognized applied version means some other process already moved
	// this database further (or differently) than this binary
	// understands; proceeding would risk operating on a schema shape this
	// binary was never built or tested against.
	for version := range applied {
		if !knownSet[version] {
			return fmt.Errorf("migrate: database has migration %q applied, which this binary's embedded migrations do not recognize; refusing to start", version)
		}
	}

	// The applied set must be a prefix of the known, ordered set: no
	// migration may be applied while an earlier one in filename order is
	// not. A gap means a migration was skipped or its record was lost,
	// and building forward from there would assume a schema shape that
	// was never actually created.
	haveAppliedOne := false
	haveGap := false
	for _, name := range known {
		if applied[name] {
			if haveGap {
				return fmt.Errorf("migrate: migration %q is applied but an earlier migration is not; database history has a gap, refusing to start", name)
			}
			haveAppliedOne = true
			continue
		}
		if haveAppliedOne {
			haveGap = true
		}
	}
	return nil
}

// applyOne executes one migration's SQL and records it as applied in a
// single transaction, so a failure partway through a migration's own
// statements never leaves it half-applied and unrecorded.
//
// insertVersion is the calling dialect's own version-record statement
// (see migrationSource), taking the migration name and the applied-at
// time as its two parameters. It is passed in rather than written here
// because its placeholder spelling is the one part of this function that
// is not portable across dialects.
//
// script may hold many statements. Both supported drivers execute a
// multi-statement script in a single zero-argument ExecContext: SQLite
// natively, and lib/pq through the simple query protocol, which it
// selects precisely because no arguments are bound here.
func applyOne(ctx context.Context, db *sql.DB, insertVersion, name, script string) error {
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("migrate: beginning transaction for %s: %w", name, err)
	}
	// Roll back on any early return. A commit sets committed to true
	// first, so this is a no-op on the success path.
	committed := false
	defer func() {
		if !committed {
			_ = tx.Rollback()
		}
	}()

	if _, err := tx.ExecContext(ctx, script); err != nil {
		return fmt.Errorf("migrate: applying %s: %w", name, err)
	}
	if _, err := tx.ExecContext(ctx, insertVersion, name, time.Now().UTC()); err != nil {
		return fmt.Errorf("migrate: recording %s as applied: %w", name, err)
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("migrate: committing %s: %w", name, err)
	}
	committed = true
	return nil
}
